package android.net;import java.util.*;public class Uri{public String raw;public Uri(String s){raw=s;}public static Uri parse(String s){return new Uri(s);}public String getAuthority(){return java.net.URI.create(raw).getAuthority();}public String getPath(){return java.net.URI.create(raw).getPath();}public String getLastPathSegment(){String p=getPath();return p.substring(p.lastIndexOf('/')+1);}public List<String> getPathSegments(){return Arrays.asList(getPath().substring(1).split("/"));}public boolean equals(Object o){return o instanceof Uri&&raw.equals(((Uri)o).raw);}public int hashCode(){return raw.hashCode();}public String toString(){return raw;}}
